// AHA PREVENT State
  const [sexo, setSexo] = useState<'M' | 'F' | null>(null);
  const [idade, setIdade] = useState('');
  const [pas, setPas] = useState('');
  const [colTotal, setColTotal] = useState('');
  const [hdl, setHdl] = useState('');
  const [imcPrevent, setImcPrevent] = useState('');
  const [egfr, setEgfr] = useState('');
  const [usaAntiHipertensivo, setUsaAntiHipertensivo] = useState(false);
  const [usaEstatina, setUsaEstatina] = useState(false);
  const [diabetes, setDiabetes] = useState(false);
  const [tabagista, setTabagista] = useState(false);
  const [riscoCVD10, setRiscoCVD10] = useState<number | null>(null);
  const [riscoASCVD10, setRiscoASCVD10] = useState<number | null>(null);
  const [riscoHF10, setRiscoHF10] = useState<number | null>(null);

  const resetPrevent = () => {
    setSexo(null);
    setIdade('');
    setPas('');
    setColTotal('');
    setHdl('');
    setImcPrevent('');
    setEgfr('');
    setUsaAntiHipertensivo(false);
    setUsaEstatina(false);
    setDiabetes(false);
    setTabagista(false);
    setRiscoCVD10(null);
    setRiscoASCVD10(null);
    setRiscoHF10(null);
  };

  const calcularPrevent = () => {
    if (!sexo || !idade || !pas || !colTotal || !hdl || !imcPrevent || !egfr) {
      alert("Por favor, preencha todos os campos obrigatórios para calcular o risco.");
      return;
    }

    try {
      const inp = {
        age: parseFloat(idade),
        sex: sexo === 'M' ? 'male' : 'female',
        sbp: parseFloat(pas),
        total_c: parseFloat(colTotal),
        hdl_c: parseFloat(hdl),
        bmi: parseFloat(imcPrevent),
        egfr: parseFloat(egfr),
        dm: diabetes,
        smoking: tabagista,
        bp_tx: usaAntiHipertensivo,
        statin: usaEstatina,
        chol_unit: "mg/dL"
      };

      const result = PREVENT.estimate(inp, "base", PREVENT_COEFFS, 4);
      setRiscoCVD10(Math.round((result.r10 as any).total_cvd * 1000) / 10);
      setRiscoASCVD10(Math.round((result.r10 as any).ascvd * 1000) / 10);
      setRiscoHF10(Math.round((result.r10 as any).heart_failure * 1000) / 10);
    } catch (e) {
      console.error(e);
      alert("Ocorreu um erro no cálculo. Verifique se os dados estão corretos.");
    }
  };

pedzState:
// Pedz / Curvas de Crescimento State
const [sexoPedz, setSexoPedz] = useState<'M' | 'F' | null>(null);
const [refPedz, setRefPedz] = useState<'OMS' | 'ZEMEL'>('OMS');
const [idadeAnosPedz, setIdadeAnosPedz] = useState('');
const [idadeMesesPedz, setIdadeMesesPedz] = useState('');
const [estaturaPedz, setEstaturaPedz] = useState('');
const [pesoPedz, setPesoPedz] = useState('');
const [pesoUnidadePedz, setPesoUnidadePedz] = useState<'kg' | 'g'>('kg');
const [perimetroPedz, setPerimetroPedz] = useState('');

const [resultadoPedz, setResultadoPedz] = useState<any | null>(null);

const resetPedz = () => {
  setSexoPedz(null);
  setRefPedz('OMS');
  setIdadeAnosPedz('');
  setIdadeMesesPedz('');
  setEstaturaPedz('');
  setPesoPedz('');
  setPesoUnidadePedz('kg');
  setPerimetroPedz('');
  setResultadoPedz(null);
};

const setAtalhoIdade = (mesesTotal: number) => {
  setIdadeAnosPedz(Math.floor(mesesTotal / 12).toString());
  setIdadeMesesPedz((mesesTotal % 12).toString());
};

const normalCDF = (x: number) => {
  const sign = x < 0 ? -1 : 1;
  x = Math.abs(x) / Math.sqrt(2.0);
  const t = 1.0 / (1.0 + 0.3275911 * x);
  const a1 =  0.254829592;
  const a2 = -0.284496736;
  const a3 =  1.421413741;
  const a4 = -1.453152027;
  const a5 =  1.061405429;
  const erf = 1.0 - (((((a5 * t + a4) * t) + a3) * t + a2) * t + a1) * t * Math.exp(-x * x);
  return 0.5 * (1.0 + sign * erf);
};

const zToPercentile = (z: number | null) => {
  if (z === null) return null;
  return Math.round(normalCDF(z) * 1000) / 10;
};

const calcularPedz = async () => {
  if (!sexoPedz) {
    alert("Por favor, selecione o sexo biológico.");
    return;
  }
  const anos = parseFloat(idadeAnosPedz) || 0;
  const meses = parseFloat(idadeMesesPedz) || 0;
  if (!idadeAnosPedz && !idadeMesesPedz) {
    alert("Por favor, informe a idade do paciente.");
    return;
  }

  const totalMeses = anos * 12 + meses;
  const isMasculino = sexoPedz === 'M';

  if (!estaturaPedz && !pesoPedz && !perimetroPedz) {
    alert("Por favor, informe pelo menos um dos valores: estatura, peso ou perímetro cefálico.");
    return;
  }

  const pPesoKilos = pesoPedz ? parseFloat(pesoPedz) * (pesoUnidadePedz === 'g' ? 0.001 : 1) : undefined;
  const estaturaMeters = estaturaPedz ? parseFloat(estaturaPedz) / 100 : undefined;
  const imc = (pPesoKilos && estaturaMeters) ? (pPesoKilos / (estaturaMeters * estaturaMeters)) : null;

  // Use @pedi-growth/core for exact calculations
  const measurementDate = new Date();
  const dob = new Date(measurementDate);
  dob.setFullYear(dob.getFullYear() - anos);
  dob.setMonth(dob.getMonth() - meses);

  try {
    const assessment = await calculateAll({
      sex: isMasculino ? 'male' : 'female',
      dateOfBirth: dob,
      dateOfMeasurement: measurementDate,
      weight: pPesoKilos,
      lengthHeight: estaturaPedz ? parseFloat(estaturaPedz) : undefined,
      headCircumference: perimetroPedz ? parseFloat(perimetroPedz) : undefined,
      chartSet: refPedz === 'OMS' ? 'who-standard' : 'down-syndrome', // Simplification, using Down if not OMS for now, though we should only support WHO or CDC. We'll just stick to OMS since pedi-growth only supports WHO for typical children.
    });

    let zEstatura: number | null = null;
    let pEstatura: number | null = null;
    let zPeso: number | null = null;
    let pPeso: number | null = null;
    let zImc: number | null = null;
    let pImc: number | null = null;
    let zPerimetro: number | null = null;
    let pPerimetro: number | null = null;

    assessment.results.forEach(res => {
      if (res.indicator === 'length-height-for-age') {
        zEstatura = Math.round(res.zScore * 100) / 100;
        pEstatura = Math.round(res.percentile * 10) / 10;
      } else if (res.indicator === 'weight-for-age') {
        zPeso = Math.round(res.zScore * 100) / 100;
        pPeso = Math.round(res.percentile * 10) / 10;
      } else if (res.indicator === 'bmi-for-age') {
        zImc = Math.round(res.zScore * 100) / 100;
        pImc = Math.round(res.percentile * 10) / 10;
      } else if (res.indicator === 'head-circumference-for-age') {
        zPerimetro = Math.round(res.zScore * 100) / 100;
        pPerimetro = Math.round(res.percentile * 10) / 10;
      }
    });

    setResultadoPedz({
      totalMeses,
      sexo: sexoPedz,
      estatura: estaturaPedz ? parseFloat(estaturaPedz) : null,
      peso: pPesoKilos !== undefined ? pPesoKilos : null,
      imc: imc !== null ? Math.round(imc * 10) / 10 : null,
      zEstatura,
      zPeso,
      zImc,
      zPerimetro,
      pEstatura,
      pPeso,
      pImc,
      pPerimetro
    });
  } catch (e) {
    console.error(e);
    alert("Erro ao calcular os índices Z-Escore com as curvas da OMS. Verifique os valores inseridos.");
  }
};

